 bool FromSlider(DependencyObject element){while(element!=null){if(element is System.Windows.Controls.Primitives.RangeBase||element is System.Windows.Controls.Primitives.Thumb)return true;try{element=VisualTreeHelper.GetParent(element);}catch{return false;}}return false;}
 void Press(object sender,MouseButtonEventArgs e){if(FromSlider(e.OriginalSource as DependencyObject))return;pressed=true;dragged=false;pressScreen=PointToScreen(e.GetPosition(this));pressLeft=Left;pressTop=Top;CaptureMouse();e.Handled=true;}
 void Move(object sender,MouseEventArgs e){if(!pressed||locked||e.LeftButton!=MouseButtonState.Pressed)return;Point now=PointToScreen(e.GetPosition(this));Vector delta=now-pressScreen;if(!dragged&&delta.Length<6)return;dragged=true;var source=PresentationSource.FromVisual(this);if(source!=null)delta=source.CompositionTarget.TransformFromDevice.Transform(delta);Left=pressLeft+delta.X;Top=pressTop+delta.Y;}
 void Release(object sender,MouseButtonEventArgs e){if(!pressed)return;bool reply=!dragged;Point pt=e.GetPosition(portrait);pressed=false;ReleaseMouseCapture();if(dragged){Clamp();SaveOwnSettings();}else if(reply&&pt.X>=0&&pt.Y>=0&&pt.X<portrait.ActualWidth&&pt.Y<portrait.ActualHeight)portrait.React();e.Handled=true;}
 void WriteDisplayState(string effort,bool inherited,bool connected){string stamp=selected+"/"+effort+"/"+inherited+"/"+connected+"/"+autoMode+"/"+auto.Hint+"/"+economy;if(stamp==stateStamp)return;try{string dir=Path.Combine(root,"runtime");Directory.CreateDirectory(dir);string file=Path.Combine(dir,"display-state.json"),tmp=file+".tmp";File.WriteAllText(tmp,Json.Encode(new{version="1.4.1",readOnly=true,threadId=selected,effort=effort,inherited=inherited,connected=connected,form=DisplayState.Form(effort),motionEnabled=portrait.MotionEnabled,autoFollow=autoMode,followSource=autoMode?auto.Source:"manual",followHint=autoMode?auto.Hint:"手动选择",economy=economy,utc=DateTime.UtcNow.ToString("O")}));if(File.Exists(file))File.Replace(tmp,file,null);else File.Move(tmp,file);stateStamp=stamp;}catch{}}
 void LoadCatalog(){try{entries=Catalog.Threads(home);var x=entries.Find(e=>e.Id==selected);if(x!=null)selectedTitle=x.Title;}catch(Exception e){Log("catalog",e.GetType().Name);} }
 void UpdateTarget(){target.Text=(autoMode?"自动 · ":"手动 · ")+selectedTitle;badge.ToolTip="只读跟随："+selectedTitle+"\n不修改 Codex 的模型或思考档位\n点击角色有回应；拖动移动位置\n右键可切换模式、聊天或退出";}
 void SetForm(string k){if(!images.ContainsKey(k))return;if(form!=k){portrait.Form=k;portrait.Source=images[k];form=k;}portrait.Opacity=1;}
 async Task Tick(){if(closing||!await tickGate.WaitAsync(0))return;try{if(DateTime.UtcNow>=nextWindowCheck){nextWindowCheck=DateTime.UtcNow.AddSeconds(2);bool previous=visibleCodex;host=await Task.Run(()=>DesktopHost.Scan());if(closing)return;string identity=host.Identity;bool restarted=identity!=hostIdentity;hostIdentity=identity;visibleCodex=identity.Length>0&&host.VisibleWindows>0;if(restarted||previous&&!visibleCodex){if(link!=null){link.Dispose();link=null;}WriteDisplayState(null,false,false);}if((restarted||!previous)&&visibleCodex){retryAt=DateTime.MinValue;failures=0;status.Text="只读 · 重新连接";LoadCatalog();UpdateTarget();}Opacity=visibleCodex?1:0;IsHitTestVisible=visibleCodex;}
  if(!visibleCodex)return;
  if(autoMode&&DateTime.UtcNow>=nextFollow){nextFollow=DateTime.UtcNow.AddMilliseconds(600);int followGeneration=generation;await Task.Run(()=>auto.Update(host));if(closing||!autoMode||followGeneration!=generation)return;string detected=auto.ThreadId;if(detected!=selected){selected=detected;generation++;failures=0;retryAt=DateTime.MinValue;selectedTitle="等待当前聊天";LoadCatalog();if(selected!=null&&selectedTitle=="等待当前聊天")selectedTitle=selected.Substring(0,8);SaveOwnSettings();}if(selected==null){status.Text="只读 · "+auto.Hint;target.Text="自动跟随 · 等待明确目标";portrait.Opacity=.45;WriteDisplayState(null,false,false);return;}}
  if(String.IsNullOrEmpty(selected)||DateTime.UtcNow<retryAt)return;
