 finally{tickGate.Release();}}
 void OpenMenu(){menu=new ContextMenu();var title=new MenuItem{Header="龙娘形态 · 只读显示",IsEnabled=false};menu.Items.Add(title);var visualPreview=new MenuItem{Header="六档动画预览（不改 Codex）"};visualPreview.Click+=(s,e)=>Process.Start(new ProcessStartInfo(Path.Combine(root,"DragonDisplay.exe"),"--preview=six"){UseShellExecute=false});menu.Items.Add(visualPreview);var automatic=new MenuItem{Header="自动跟随侧栏当前聊天",IsCheckable=true,IsChecked=autoMode};automatic.Click+=(s,e)=>{autoMode=!autoMode;nextFollow=DateTime.MinValue;generation++;retryAt=DateTime.MinValue;failures=0;SaveOwnSettings();var ignored=Tick();};menu.Items.Add(automatic);var lean=new MenuItem{Header="省电模式（20 帧 / 减少星光）",IsCheckable=true,IsChecked=economy};lean.Click+=(s,e)=>{economy=!economy;portrait.EconomyMode=economy;SaveOwnSettings();};menu.Items.Add(lean);var chats=new MenuItem{Header="手动指定聊天（备用）"};LoadCatalog();foreach(var x in entries){ThreadEntry entry=x;var item=new MenuItem{Header=entry.Title.Replace("_","__"),IsCheckable=true,IsChecked=entry.Id==selected};item.Click+=(s,e)=>{autoMode=false;selected=entry.Id;selectedTitle=entry.Title;generation++;failures=0;retryAt=DateTime.MinValue;portrait.Opacity=.45;status.Text="只读 · 同步中";UpdateTarget();SaveOwnSettings();var ignored=Tick();};chats.Items.Add(item);}if(entries.Count==0)chats.Items.Add(new MenuItem{Header="暂无可读取的聊天",IsEnabled=false});menu.Items.Add(chats);
