 void Clamp(){Rect r=SystemParameters.WorkArea;if(Double.IsNaN(Left)||Left<r.Left||Left+Width>r.Right)Left=r.Left+30;if(Double.IsNaN(Top)||Top<r.Top||Top+Height>r.Bottom)Top=Math.Max(r.Top,r.Bottom-Height-30);}
 void ReadOwnSettings(string seed){Left=30;Top=Math.Max(0,SystemParameters.WorkArea.Bottom-Height-30);try{string path=Path.Combine(root,"runtime","settings.json");if(!File.Exists(path))return;var d=Json.Decode(File.ReadAllText(path));if(String.IsNullOrEmpty(seed))selected=Json.Str(d,"threadId");object v=Json.Get(d,"scale");if(v!=null){scale=Convert.ToDouble(v);if(scale<.75||scale>1.25)scale=1;}Width=340*scale;Height=520*scale;v=Json.Get(d,"left");if(v!=null)Left=Convert.ToDouble(v);v=Json.Get(d,"top");if(v!=null)Top=Convert.ToDouble(v);locked=true.Equals(Json.Get(d,"locked"));autoMode=!false.Equals(Json.Get(d,"autoFollow"));economy=true.Equals(Json.Get(d,"economy"));portrait.EconomyMode=economy;}catch{}}
 void SaveOwnSettings(){if(export||preview!=null)return;try{string dir=Path.Combine(root,"runtime");Directory.CreateDirectory(dir);string file=Path.Combine(dir,"settings.json"),tmp=file+".tmp";File.WriteAllText(tmp,Json.Encode(new{threadId=selected,left=Left,top=Top,scale=scale,locked=locked,autoFollow=autoMode,economy=economy}),new UTF8Encoding(false));if(File.Exists(file))File.Replace(tmp,file,null);else File.Move(tmp,file);}catch{}}
 void Log(string kind,string code){try{string dir=Path.Combine(root,"runtime");Directory.CreateDirectory(dir);string path=Path.Combine(dir,"diagnostic.log");if(File.Exists(path)&&new FileInfo(path).Length>262144){string old=path+".1";if(File.Exists(old))File.Delete(old);File.Move(path,old);}File.AppendAllText(path,DateTime.UtcNow.ToString("O")+" "+kind+" "+code+Environment.NewLine);}catch{}}
 void RenderAll(){var dir=Path.Combine(root,"verification");Directory.CreateDirectory(dir);foreach(string k in new[]{"chibi","medium","full","xhigh","max","ultra"}){SetForm(k);status.Text=k+" · 六档独立形态";target.Text="只读显示 · 不修改 Codex";portrait.Step(1.4);Measure(new Size(Width,Height));Arrange(new Rect(0,0,Width,Height));UpdateLayout();var b=new RenderTargetBitmap((int)Width*2,(int)Height*2,192,192,PixelFormats.Pbgra32);b.Render(this);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(Path.Combine(dir,"preview-"+k+".png")))enc.Save(f);}}
