 [STAThread]public static void Main(string[] args){string root=AppDomain.CurrentDomain.BaseDirectory;try{string home=Environment.GetEnvironmentVariable("CODEX_HOME");if(String.IsNullOrEmpty(home))home=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".codex");string thread=null,preview=null;bool export=args.Contains("--render-all");foreach(string a in args){if(a.StartsWith("--thread="))thread=a.Substring(9);if(a.StartsWith("--preview="))preview=a.Substring(10);}if(thread!=null&&!System.Text.RegularExpressions.Regex.IsMatch(thread,@"^[0-9a-fA-F-]{36}$"))throw new Exception("无效聊天标识");bool fresh;using(var mutex=new Mutex(true,"Local\\CodexDragonDisplay.ReadOnly.1"+(preview!=null||export?".Preview":""),out fresh)){if(!fresh)return;var app=new Application();app.Run(new VisualWindow(root,home,thread,preview,export));}}
 catch(Exception e){Directory.CreateDirectory(Path.Combine(root,"runtime"));File.WriteAllText(Path.Combine(root,"runtime","startup-error.txt"),e.ToString());MessageBox.Show("龙娘显示组件启动失败。详情保存在安装目录 runtime/startup-error.txt。\n不会修改 Codex 设置。","龙娘形态 · 只读显示");}}
